INSERT INTO modules (id,title,description,icon,position,status) VALUES
(1,E'Introducción a Excel',E'Conoce qué es Excel, su entorno de trabajo y los conceptos básicos: libros, hojas, celdas, tipos de datos y fórmulas.',E'bi-lightbulb',1,E'active'),
(2,E'Formato y organización',E'Aprende a presentar la información con formato de celdas, números, bordes, colores y tablas.',E'bi-palette',2,E'active'),
(3,E'Operaciones y fórmulas básicas',E'Domina las cuatro operaciones, las referencias relativas y absolutas y la jerarquía de operadores.',E'bi-plus-slash-minus',3,E'active'),
(4,E'Funciones básicas',E'Usa las funciones fundamentales: SUMA, PROMEDIO, MAX, MIN, CONTAR y CONTARA.',E'bi-calculator',4,E'active'),
(5,E'Funciones condicionales',E'Toma decisiones con SI y calcula con criterios usando CONTAR.SI, SUMAR.SI y PROMEDIO.SI.',E'bi-signpost-split',5,E'active'),
(6,E'Organización de datos',E'Ordena, filtra y busca información; controla lo que se escribe con validación y resalta con formato condicional.',E'bi-funnel',6,E'active'),
(7,E'Gráficos',E'Representa los datos con gráficos de barras, circulares y de líneas, e interpreta los resultados.',E'bi-bar-chart-line',7,E'active'),
(8,E'Aplicaciones prácticas',E'Aplica todo lo aprendido en situaciones reales: ventas, inventario, calificaciones, gastos y trabajadores.',E'bi-briefcase',8,E'active');
INSERT INTO lessons (id,module_id,title,description,theory,example,example_data,image_url,position,status) VALUES
(1,1,E'¿Qué es Excel?',E'Qué es una hoja de cálculo y para qué sirve.',E'<p><strong>Microsoft Excel</strong> es una <em>hoja de cálculo</em>: un programa que organiza la información en filas y columnas y realiza cálculos de forma automática. Si cambias un dato, todos los resultados que dependen de él se actualizan solos.</p><ul><li>Registrar y ordenar datos (listas, inventarios, notas).</li><li>Calcular con fórmulas y funciones.</li><li>Representar resultados con gráficos.</li></ul>',E'<p>Una lista de compras: al escribir cantidad y precio, Excel calcula el total sin necesidad de calculadora. Si el precio del cuaderno sube, el total se corrige automáticamente.</p>',E'{"headers":["Producto","Cantidad","Precio unitario"],"rows":[["Cuaderno",3,2.5],["Lápiz",10,0.4],["Borrador",2,0.75]]}',NULL,1,E'active'),
(2,1,E'Entorno de trabajo',E'Cinta de opciones, barra de fórmulas y zona de trabajo.',E'<p>La ventana de Excel se compone de:</p><ul><li><strong>Cinta de opciones:</strong> pestañas (Inicio, Insertar, Fórmulas, Datos, Vista…) con los comandos agrupados.</li><li><strong>Cuadro de nombres:</strong> muestra la dirección de la celda activa (por ejemplo B3).</li><li><strong>Barra de fórmulas:</strong> muestra y permite editar el contenido real de la celda activa.</li><li><strong>Hoja de cálculo:</strong> la cuadrícula de celdas.</li><li><strong>Pestañas de hojas y barra de estado:</strong> abajo, para cambiar de hoja y ver resúmenes como suma o promedio de la selección.</li></ul>',E'<p>Selecciona la celda B2 y observa: el Cuadro de nombres dice <code>B2</code> y la barra de fórmulas muestra su contenido. Si la celda tiene una fórmula, la celda muestra el resultado, pero la barra de fórmulas muestra la fórmula.</p>',NULL,E'assets/img/excel-entorno.svg',2,E'active'),
(3,1,E'Libros y hojas',E'La estructura de un archivo de Excel.',E'<p>Un archivo de Excel (<code>.xlsx</code>) se llama <strong>libro</strong> y contiene una o varias <strong>hojas</strong>. Cada hoja es una cuadrícula independiente.</p><ul><li>Insertar hoja: botón <strong>+</strong> junto a las pestañas.</li><li>Cambiar nombre: doble clic sobre la pestaña.</li><li>Mover o copiar: arrastrar la pestaña (con Ctrl para copiar).</li><li>Referenciar otra hoja: <code>=Ventas!B3</code> toma la celda B3 de la hoja llamada Ventas.</li></ul>',E'<p>Un libro llamado <em>Contabilidad 2026</em> puede tener una hoja por mes: Enero, Febrero, Marzo… y una hoja Resumen que suma los totales de cada mes con fórmulas como <code>=Enero!B10+Febrero!B10</code>.</p>',NULL,E'assets/img/libro-hojas.svg',3,E'active'),
(4,1,E'Filas, columnas y celdas',E'Cómo se identifican y seleccionan las celdas.',E'<p>Las <strong>columnas</strong> se nombran con letras (A, B, C… hasta XFD) y las <strong>filas</strong> con números (1 a 1 048 576). La <strong>celda</strong> es la intersección de una columna y una fila y su dirección combina ambas: <code>B3</code> es la columna B, fila 3.</p><p>Un <strong>rango</strong> es un grupo de celdas contiguas y se escribe <code>B2:B6</code> (desde B2 hasta B6).</p>',E'<p>En la tabla de ejemplo, el texto “Lápiz” está en <code>A2</code> y el número 10 está en <code>B2</code>. El rango <code>B2:B4</code> abarca las tres cantidades.</p>',E'{"headers":["Producto","Cantidad"],"rows":[["Lápiz",10],["Cuaderno",5],["Borrador",8]]}',NULL,4,E'active'),
(5,1,E'Tipos de datos',E'Texto, números, fechas y valores lógicos.',E'<p>En una celda puedes escribir distintos tipos de datos:</p><ul><li><strong>Texto:</strong> se alinea a la izquierda (nombres, códigos).</li><li><strong>Números:</strong> se alinean a la derecha y se pueden calcular.</li><li><strong>Fechas y horas:</strong> son números con formato (<code>15/03/2026</code>).</li><li><strong>Lógicos:</strong> VERDADERO o FALSO.</li><li><strong>Fórmulas:</strong> empiezan con <code>=</code>.</li></ul><p>Un dato que parece número pero está alineado a la izquierda suele ser texto y no se podrá sumar.</p>',E'<p>En una lista de clientes, el nombre es texto, la edad es un número, la fecha de registro es una fecha y la columna “Activo” podría ser VERDADERO o FALSO.</p>',E'{"headers":["Nombre","Edad","Registro","Activo"],"rows":[["Rosa Díaz",34,"15\\/03\\/2026","VERDADERO"],["Mario Paz",28,"02\\/04\\/2026","FALSO"]]}',NULL,5,E'active'),
(6,1,E'Introducción a las fórmulas',E'Cómo escribir una fórmula sencilla.',E'<p>Una <strong>fórmula</strong> siempre empieza con el signo <code>=</code>. Combina valores, referencias a celdas y operadores: <code>+</code> suma, <code>-</code> resta, <code>*</code> multiplica, <code>/</code> divide y <code>^</code> potencia.</p><p>Se confirma con <kbd>Enter</kbd> y se edita con <kbd>F2</kbd>. Lo importante: si cambias un dato referenciado, el resultado se recalcula solo.</p>',E'<p>Con cantidad en A2 y precio en B2, la fórmula <code>=A2*B2</code> da el importe. Al cambiar B2 de 2,5 a 3, el resultado pasa de 10 a 12 sin tocar la fórmula.</p>',E'{"headers":["Cantidad","Precio","Importe"],"rows":[[4,2.5,"=A2*B2"]]}',NULL,6,E'active'),
(7,2,E'Formato de celdas',E'Fuente, alineación y el cuadro Formato de celdas.',E'<p>En la pestaña <strong>Inicio</strong> encuentras fuente, tamaño, negrita (<kbd>Ctrl+N</kbd>), cursiva, alineación y color. Para más opciones usa <kbd>Ctrl+1</kbd>, que abre <strong>Formato de celdas</strong> con las pestañas Número, Alineación, Fuente, Borde, Relleno y Proteger.</p><p>Aplica el formato a una selección completa para que la tabla tenga un aspecto uniforme.</p>',E'<p>Para un encabezado: selecciona A1:C1, aplica negrita, centra el texto y pon un relleno verde claro. Así se distingue de los datos.</p>',E'{"headers":["Producto","Cantidad","Precio"],"rows":[["Cuaderno",3,2.5],["Lápiz",10,0.4]]}',NULL,1,E'active'),
(8,2,E'Formato de números',E'Moneda, porcentaje, fecha y otros formatos numéricos.',E'<p>El formato cambia <strong>cómo se ve</strong> un número, no su valor. Los más usados: General, Número (decimales), Moneda, Contabilidad, Fecha, Porcentaje, Fracción, Científico y Texto.</p><p>El formato <strong>Porcentaje</strong> multiplica visualmente por 100: el valor <code>0,25</code> se muestra como <code>25 %</code>.</p>',E'<p>Si escribes 1500 y aplicas formato Moneda con dos decimales, verás <code>$1.500,00</code>, pero el valor sigue siendo 1500 y puedes usarlo en cálculos.</p>',E'{"headers":["Valor","Formato aplicado","Se muestra"],"rows":[[1500,"Moneda","$1.500,00"],[0.25,"Porcentaje","25%"],["15\\/03\\/2026","Fecha larga","domingo, 15 de marzo de 2026"]]}',NULL,2,E'active'),
(9,2,E'Bordes y colores',E'Mejorar la lectura con bordes, rellenos y colores.',E'<p>Los <strong>bordes</strong> separan datos y los <strong>rellenos</strong> destacan encabezados o totales. Se encuentran en Inicio → Fuente (Bordes y Color de relleno).</p><p>Buenas prácticas: usar pocos colores (2 o 3), mantener buen contraste entre texto y fondo y reservar los colores llamativos para lo realmente importante.</p>',E'<p>Una tabla clara: encabezado verde oscuro con texto blanco, filas de datos con borde fino gris y la fila de totales en negrita con borde superior doble.</p>',E'{"headers":["Producto","Cantidad","Total"],"rows":[["Cuaderno",3,7.5],["Lápiz",10,4],["Total",13,11.5]]}',NULL,3,E'active'),
(10,2,E'Combinar celdas',E'Cuándo conviene combinar y cuándo no.',E'<p><strong>Combinar y centrar</strong> (Inicio → Alineación) une varias celdas en una sola. Es útil para títulos sobre una tabla.</p><p>Pero dentro de la tabla de datos <strong>no se recomienda</strong>: dificulta ordenar, filtrar y copiar. Una alternativa es <em>Centrar en la selección</em> (Formato de celdas → Alineación → Horizontal), que centra el texto sin unir celdas.</p>',E'<p>Título “Ventas del primer trimestre” centrado sobre las columnas A:D combinando A1:D1. Los datos desde la fila 3 se dejan sin combinar.</p>',NULL,NULL,4,E'active'),
(11,2,E'Ajuste de columnas y filas',E'Cambiar el ancho y alto para que todo se vea.',E'<p>Para ajustar una columna al contenido, haz <strong>doble clic</strong> en el borde derecho de su letra. También puedes arrastrar el borde o usar Inicio → Formato → Ancho de columna.</p><p>Si un número no cabe, la celda muestra <code>#####</code>: basta con ensanchar la columna. Para textos largos usa <strong>Ajustar texto</strong>, que lo distribuye en varias líneas.</p>',E'<p>La columna “Descripción” corta el texto: se ensancha con doble clic o se activa “Ajustar texto” y la fila crece sola.</p>',NULL,NULL,5,E'active'),
(12,2,E'Tablas',E'Convertir un rango en una tabla de Excel.',E'<p>Una <strong>Tabla</strong> (Insertar → Tabla, o <kbd>Ctrl+T</kbd>) añade filtros automáticos, estilos con filas alternadas, una fila de totales opcional y crece sola al agregar datos nuevos.</p><p>Requisitos: una fila de encabezados con nombres únicos y sin filas o columnas vacías en medio.</p>',E'<p>Al convertir A1:C20 en tabla y añadir un registro en la fila 21, la tabla se expande y las fórmulas y gráficos que la usan se actualizan.</p>',E'{"headers":["Producto","Cantidad","Precio"],"rows":[["Cuaderno",3,2.5],["Lápiz",10,0.4]]}',NULL,6,E'active'),
(13,3,E'Suma',E'Sumar valores con el operador +.',E'<p>El operador <code>+</code> suma valores o celdas: <code>=B2+B3</code>. Puedes encadenar varios sumandos: <code>=B2+B3+B4</code>. Cuando hay muchos datos es más práctico usar la función SUMA (módulo 4).</p>',E'<p>Con ingresos de enero, febrero y marzo en B2:B4, el total del trimestre se calcula con <code>=B2+B3+B4</code>.</p>',E'{"headers":["Mes","Ingresos"],"rows":[["Enero",1200],["Febrero",1350],["Marzo",1100]]}',NULL,1,E'active'),
(14,3,E'Resta',E'Calcular diferencias y saldos.',E'<p>El operador <code>-</code> resta: <code>=B2-B3</code>. Es la base de cálculos como el saldo (ingresos − gastos) o la diferencia entre lo planificado y lo real.</p>',E'<p>Con ingresos en B2 y gastos en B3, el saldo es <code>=B2-B3</code>. Un resultado negativo indica déficit.</p>',E'{"headers":["Concepto","Monto"],"rows":[["Ingresos",2500],["Gastos",1875]]}',NULL,2,E'active'),
(15,3,E'Multiplicación',E'Multiplicar con el operador *.',E'<p>El asterisco <code>*</code> multiplica: <code>=B2*C2</code>. Se usa para importes (cantidad × precio), porcentajes (<code>=B2*0,16</code>) y muchos otros cálculos.</p>',E'<p>Si compras 12 cuadernos a 3,50 cada uno, el importe es <code>=12*3,5</code> o, con celdas, <code>=B2*C2</code>.</p>',E'{"headers":["Producto","Cantidad","Precio","Importe"],"rows":[["Cuaderno",12,3.5,"=B2*C2"]]}',NULL,3,E'active'),
(16,3,E'División',E'Dividir y evitar el error #¡DIV/0!.',E'<p>La barra <code>/</code> divide: <code>=B2/C2</code>. Dividir entre cero es imposible y Excel muestra el error <code>#¡DIV/0!</code>. Se puede evitar con una condición (<code>=SI(C2=0;0;B2/C2)</code>, módulo 5).</p>',E'<p>Para el precio por unidad de un paquete: total en B2 y unidades en C2, <code>=B2/C2</code>. Si C2 está vacío o es 0, aparece #¡DIV/0!.</p>',E'{"headers":["Total pagado","Unidades","Precio por unidad"],"rows":[[24,6,"=A2\\/B2"]]}',NULL,4,E'active'),
(17,3,E'Referencias relativas y absolutas',E'Qué pasa con las fórmulas al copiarlas.',E'<p>Una referencia <strong>relativa</strong> (<code>B2</code>) cambia al copiar la fórmula: al bajar una fila se convierte en B3. Una <strong>absoluta</strong> (<code>$B$2</code>) permanece fija. Las <strong>mixtas</strong> fijan solo la columna (<code>$B2</code>) o solo la fila (<code>B$2</code>).</p><p>Con <kbd>F4</kbd> alternas entre los tipos mientras editas la fórmula.</p>',E'<p>Si la tasa de IVA está en E1, para calcular el IVA de cada precio usa <code>=B2*$E$1</code>. Al copiarla hacia abajo, B2 pasa a B3, B4… pero $E$1 se mantiene.</p>',E'{"headers":["Producto","Precio","","","IVA"],"rows":[["Lápiz",10,"","",0.16],["Cuaderno",25,"","",""],["Regla",8,"","",""]]}',NULL,5,E'active'),
(18,3,E'Operaciones combinadas',E'El orden en que Excel resuelve los operadores.',E'<p>Excel respeta la jerarquía: primero <strong>paréntesis</strong>, luego <strong>potencias</strong>, después <strong>multiplicación y división</strong> (de izquierda a derecha) y por último <strong>suma y resta</strong>.</p><p>Por eso <code>=2+3*4</code> da 14, mientras que <code>=(2+3)*4</code> da 20.</p>',E'<p>Para el promedio de dos notas, hay que usar paréntesis: <code>=(B2+C2)/2</code>. Sin ellos, <code>=B2+C2/2</code> divide solo C2.</p>',E'{"headers":["Nota 1","Nota 2","Promedio"],"rows":[[14,16,"=(A2+B2)\\/2"]]}',NULL,6,E'active'),
(19,4,E'Función SUMA',E'Sumar rangos de forma rápida.',E'<p>Sintaxis: <code>=SUMA(número1; [número2]; …)</code>. Acepta rangos (<code>B2:B6</code>), celdas sueltas o ambos: <code>=SUMA(B2:B3;B5)</code>. Ignora el texto y las celdas vacías.</p><p>El botón <strong>Autosuma</strong> (Σ, atajo <kbd>Alt+=</kbd>) la escribe por ti.</p>',E'<p>Para sumar las ventas de la semana en B2:B6: <code>=SUMA(B2:B6)</code>. Si agregas una venta dentro del rango, el total se actualiza.</p>',E'{"headers":["Día","Ventas"],"rows":[["Lunes",120],["Martes",150],["Miércoles",90],["Jueves",200],["Viernes",175]]}',NULL,1,E'active'),
(20,4,E'Función PROMEDIO',E'Calcular la media aritmética.',E'<p>Sintaxis: <code>=PROMEDIO(número1; [número2]; …)</code>. Suma los valores y divide entre la cantidad de números. <strong>Ignora</strong> celdas vacías y texto (pero no los ceros).</p>',E'<p>Para el promedio de las notas de B2:B5: <code>=PROMEDIO(B2:B5)</code>.</p>',E'{"headers":["Alumno","Nota"],"rows":[["Ana",15],["Luis",12],["Marta",18],["Pedro",11]]}',NULL,2,E'active'),
(21,4,E'Función MAX',E'Encontrar el valor más alto.',E'<p>Sintaxis: <code>=MAX(número1; [número2]; …)</code>. Devuelve el mayor valor de un rango. Muy útil para detectar la venta más alta, la nota máxima o el precio más caro.</p>',E'<p>Con las ventas en B2:B6, <code>=MAX(B2:B6)</code> devuelve 200, la venta del jueves.</p>',E'{"headers":["Día","Ventas"],"rows":[["Lunes",120],["Martes",150],["Miércoles",90],["Jueves",200],["Viernes",175]]}',NULL,3,E'active'),
(22,4,E'Función MIN',E'Encontrar el valor más bajo.',E'<p>Sintaxis: <code>=MIN(número1; [número2]; …)</code>. Devuelve el menor valor del rango. Complementa a MAX para calcular rangos o detectar mínimos.</p>',E'<p>Con temperaturas en B2:B6, <code>=MIN(B2:B6)</code> da la más baja de la semana.</p>',E'{"headers":["Ciudad","Temperatura"],"rows":[["Caracas",28],["Maracay",31],["Mérida",25],["Maracaibo",33],["Valencia",29]]}',NULL,4,E'active'),
(23,4,E'Función CONTAR',E'Contar celdas que contienen números.',E'<p>Sintaxis: <code>=CONTAR(valor1; [valor2]; …)</code>. Cuenta únicamente las celdas con <strong>números</strong> (y fechas). Ignora texto, errores y celdas vacías.</p>',E'<p>En la lista de lecturas, <code>=CONTAR(A2:A6)</code> cuenta solo las celdas numéricas y no el texto “N/D”.</p>',E'{"headers":["Lecturas"],"rows":[[10],["N\\/D"],[25],[""],[40]]}',NULL,5,E'active'),
(24,4,E'Función CONTARA',E'Contar celdas que no están vacías.',E'<p>Sintaxis: <code>=CONTARA(valor1; [valor2]; …)</code>. Cuenta las celdas <strong>no vacías</strong>, sin importar si contienen texto o números. Sirve para saber cuántos registros hay en una lista.</p>',E'<p>Con la misma lista de lecturas, <code>=CONTARA(A2:A6)</code> también cuenta el texto “N/D”, pero no la celda vacía.</p>',E'{"headers":["Lecturas"],"rows":[[10],["N\\/D"],[25],[""],[40]]}',NULL,6,E'active'),
(25,5,E'Función SI',E'Tomar decisiones según una condición.',E'<p>Sintaxis: <code>=SI(prueba_lógica; valor_si_verdadero; valor_si_falso)</code>. Evalúa una condición y devuelve un resultado u otro. Operadores de comparación: <code>&gt;</code>, <code>&lt;</code>, <code>&gt;=</code>, <code>&lt;=</code>, <code>=</code> y <code>&lt;&gt;</code> (distinto). El texto va entre comillas.</p>',E'<p>Para indicar si un alumno aprobó con nota mínima 10: <code>=SI(B2&gt;=10;"Aprobado";"Reprobado")</code>.</p>',E'{"headers":["Alumno","Nota","Condición"],"rows":[["Ana",15,"Aprobado"],["Pedro",8,"Reprobado"]]}',NULL,1,E'active'),
(26,5,E'Función CONTAR.SI',E'Contar celdas que cumplen un criterio.',E'<p>Sintaxis: <code>=CONTAR.SI(rango; criterio)</code>. Cuenta cuántas celdas del rango cumplen el criterio. El criterio puede ser un valor (<code>"Aprobado"</code>) o una comparación entre comillas (<code>"&gt;10"</code>).</p>',E'<p>Para saber cuántos alumnos aprobaron: <code>=CONTAR.SI(B2:B6;"Aprobado")</code>.</p>',E'{"headers":["Alumno","Condición"],"rows":[["Ana","Aprobado"],["Luis","Reprobado"],["Marta","Aprobado"],["Pedro","Aprobado"],["Sofía","Reprobado"]]}',NULL,2,E'active'),
(27,5,E'Función SUMAR.SI',E'Sumar solo los valores que cumplen un criterio.',E'<p>Sintaxis: <code>=SUMAR.SI(rango; criterio; [rango_suma])</code>. Recorre el rango buscando el criterio y suma los valores correspondientes del rango_suma.</p>',E'<p>Para sumar las ventas de Ana: <code>=SUMAR.SI(A2:A6;"Ana";B2:B6)</code>.</p>',E'{"headers":["Vendedor","Ventas"],"rows":[["Ana",500],["Luis",300],["Ana",450],["Luis",200],["Marta",600]]}',NULL,3,E'active'),
(28,5,E'Función PROMEDIO.SI',E'Promediar solo lo que cumple un criterio.',E'<p>Sintaxis: <code>=PROMEDIO.SI(rango; criterio; [rango_promedio])</code>. Calcula la media únicamente de las filas que cumplen el criterio.</p>',E'<p>Promedio de las notas de la sección A: <code>=PROMEDIO.SI(A2:A6;"A";B2:B6)</code>.</p>',E'{"headers":["Sección","Nota"],"rows":[["A",14],["B",12],["A",16],["B",10],["A",18]]}',NULL,4,E'active'),
(29,6,E'Ordenar información',E'Ordenar datos por uno o varios criterios.',E'<p>En Datos → Ordenar, o con los botones A→Z / Z→A, puedes ordenar alfabética o numéricamente. Con <strong>Ordenar</strong> personalizado añades niveles (por ejemplo, primero por departamento y luego por salario).</p><p><strong>Importante:</strong> selecciona toda la tabla o una sola celda de ella; si ordenas una única columna aislada, se rompe la correspondencia entre los datos de cada fila.</p>',E'<p>Para ver los salarios de mayor a menor, haz clic en una celda de la columna Salario y pulsa Ordenar de Z a A. Todas las filas se mueven juntas.</p>',E'{"headers":["Nombre","Departamento","Salario"],"rows":[["Elena","Admin",1000],["Carla","Ventas",900],["Diego","Ventas",1100]]}',NULL,1,E'active'),
(30,6,E'Filtros',E'Mostrar solo las filas que interesan.',E'<p>Activa los filtros con Datos → Filtro o <kbd>Ctrl+Mayús+L</kbd>. En cada encabezado aparece una flecha para filtrar por texto, número, fecha o color.</p><p>Un filtro <strong>no elimina</strong> filas: solo las oculta (los números de fila cambian a azul). Se quita con “Borrar filtro”.</p>',E'<p>Filtra la columna Departamento por “Ventas” y verás solo esos trabajadores. Los demás siguen en la hoja, solo ocultos.</p>',E'{"headers":["Nombre","Departamento","Salario"],"rows":[["Elena","Admin",1000],["Carla","Ventas",900],["Diego","Ventas",1100]]}',NULL,2,E'active'),
(31,6,E'Buscar información',E'Buscar valores en una tabla con BUSCARV.',E'<p>Para buscar texto en la hoja usa <kbd>Ctrl+B</kbd> (Buscar) y <kbd>Ctrl+L</kbd> (Reemplazar). Para recuperar datos de una tabla se usa <code>=BUSCARV(valor_buscado; matriz; columna; [ordenado])</code>.</p><ul><li><em>valor_buscado:</em> el código que quieres encontrar.</li><li><em>matriz:</em> la tabla donde buscar (el valor buscado debe estar en la primera columna).</li><li><em>columna:</em> número de columna con el dato a devolver.</li><li><em>ordenado:</em> FALSO (o 0) para coincidencia exacta.</li></ul>',E'<p>Para obtener el producto del código 103: <code>=BUSCARV(103;A2:C4;2;FALSO)</code> devuelve “Regla”.</p>',E'{"headers":["Código","Producto","Precio"],"rows":[[101,"Lápiz",0.5],[102,"Cuaderno",2.5],[103,"Regla",1.2]]}',NULL,3,E'active'),
(32,6,E'Validación de datos',E'Controlar qué valores se pueden escribir.',E'<p>En Datos → Validación de datos defines reglas para una celda: <strong>lista desplegable</strong>, números enteros o decimales entre un mínimo y máximo, fechas, longitud del texto o una fórmula propia. Puedes añadir un mensaje de entrada y un mensaje de error.</p>',E'<p>En la columna “Estado”, se crea una lista con “Aprobado;Reprobado”. Al hacer clic en la celda aparece una flecha con las dos opciones y no se acepta nada más.</p>',NULL,NULL,4,E'active'),
(33,6,E'Formato condicional',E'Resaltar datos automáticamente según reglas.',E'<p>En Inicio → Formato condicional creas reglas que cambian el aspecto de las celdas según su valor: <strong>resaltar celdas</strong> (mayor que, menor que, entre, texto que contiene), <strong>barras de datos</strong>, <strong>escalas de color</strong> y <strong>conjuntos de iconos</strong>. Si el dato cambia, el formato se actualiza solo.</p>',E'<p>Para resaltar en rojo las notas menores a 10: selecciona B2:B20 → Formato condicional → Resaltar reglas de celdas → Es menor que → 10.</p>',E'{"headers":["Alumno","Nota"],"rows":[["Ana",15],["Pedro",8],["Marta",18]]}',NULL,5,E'active'),
(34,7,E'Gráficos de barras',E'Comparar valores entre categorías.',E'<p>Los gráficos de <strong>barras</strong> (horizontales) y <strong>columnas</strong> (verticales) comparan magnitudes entre categorías: ventas por sucursal, notas por alumno, gastos por rubro. Se crean seleccionando los datos (con encabezados) y eligiendo Insertar → Gráficos.</p>',E'<p>Con las ventas de cuatro sucursales, un gráfico de columnas permite ver de un vistazo cuál vende más y cuál menos.</p>',E'{"headers":["Sucursal","Ventas"],"rows":[["Centro",5200],["Norte",4100],["Sur",3800],["Este",4700]]}',E'assets/img/grafico-barras.svg',1,E'active'),
(35,7,E'Gráficos circulares',E'Mostrar la proporción de cada parte en un total.',E'<p>El gráfico <strong>circular</strong> muestra qué porcentaje del total representa cada categoría. Úsalo con <strong>una sola serie</strong> de datos y pocas categorías (hasta unas 6), cuyos valores sumen un todo (100 %). Agrega etiquetas de porcentaje para facilitar la lectura.</p>',E'<p>La distribución de los gastos del mes (vivienda, comida, transporte, ocio) se entiende bien en un gráfico circular.</p>',E'{"headers":["Categoría","Gasto"],"rows":[["Vivienda",450],["Comida",280],["Transporte",75],["Ocio",40]]}',E'assets/img/grafico-circular.svg',2,E'active'),
(36,7,E'Gráficos de líneas',E'Representar tendencias en el tiempo.',E'<p>El gráfico de <strong>líneas</strong> une puntos consecutivos y es ideal para mostrar la <strong>evolución</strong> de un dato en el tiempo: ventas mensuales, temperatura por hora, inscripciones por año. Permite comparar varias series en el mismo gráfico.</p>',E'<p>Con las ventas de seis meses, una línea ascendente indica crecimiento, y una caída marcada señala un problema que investigar.</p>',E'{"headers":["Mes","Ventas"],"rows":[["Ene",1000],["Feb",1200],["Mar",900],["Abr",1500],["May",1650],["Jun",1800]]}',E'assets/img/grafico-lineas.svg',3,E'active'),
(37,7,E'Interpretación de resultados',E'Leer un gráfico y sacar conclusiones.',E'<p>Un gráfico bien hecho tiene <strong>título</strong>, <strong>ejes rotulados</strong>, <strong>leyenda</strong> cuando hay varias series y escalas claras. Para interpretarlo: identifica el máximo y el mínimo, compara categorías, observa la tendencia y busca valores atípicos. Finalmente, redacta una conclusión con tus palabras.</p>',E'<p>En las ventas de enero a abril, marzo cae por debajo de enero y abril logra el mayor valor: la conclusión es una recuperación fuerte tras el bajón de marzo.</p>',E'{"headers":["Mes","Ventas"],"rows":[["Enero",1000],["Febrero",1200],["Marzo",900],["Abril",1500]]}',NULL,4,E'active'),
(38,8,E'Control de ventas',E'Registrar ventas y calcular importes y totales.',E'<p>Una hoja de ventas típica tiene Producto, Cantidad, Precio e Importe (<code>=B2*C2</code>). Al final se calcula el total con <code>=SUMA(D2:D4)</code>. Con SUMAR.SI puedes sumar por vendedor o por producto, y un gráfico ayuda a comparar resultados.</p>',E'<p>Con tres productos vendidos, el importe de cada línea se calcula con una multiplicación y el total del día con SUMA.</p>',E'{"headers":["Producto","Cantidad","Precio"],"rows":[["Camisa",3,20],["Pantalón",2,35],["Gorra",5,8]]}',NULL,1,E'active'),
(39,8,E'Control de inventario',E'Controlar existencias y detectar reposiciones.',E'<p>En un inventario registras entradas y salidas: <code>existencia = entradas − salidas</code>. El <strong>valor del inventario</strong> es existencia × costo. Con SI puedes generar alertas: <code>=SI(B2&lt;C2;"Reponer";"OK")</code>, y con formato condicional resaltarlas.</p>',E'<p>Si el arroz tiene 8 unidades y el mínimo es 10, la fórmula muestra “Reponer” para que se haga un pedido.</p>',E'{"headers":["Producto","Existencia","Mínimo"],"rows":[["Arroz",8,10],["Harina",25,12],["Aceite",4,6]]}',NULL,2,E'active'),
(40,8,E'Registro de calificaciones',E'Calcular promedios y condiciones de aprobación.',E'<p>Una planilla de notas calcula el promedio por alumno (<code>=PROMEDIO(B2:D2)</code>), la condición (<code>=SI(E2&gt;=10;"Aprobado";"Reprobado")</code>), el promedio del curso y cuántos aprobaron con <code>=CONTAR.SI(F2:F20;"Aprobado")</code>.</p>',E'<p>Ana tiene 16, 14 y 18: su promedio es 16 y aprueba. Luis tiene 10, 8 y 9: su promedio es 9 y reprueba.</p>',E'{"headers":["Alumno","Nota 1","Nota 2","Nota 3"],"rows":[["Ana",16,14,18],["Luis",10,8,9]]}',NULL,3,E'active'),
(41,8,E'Control de gastos',E'Clasificar gastos y calcular su peso en el total.',E'<p>Para controlar gastos: registra fecha, concepto, categoría y monto; suma por categoría con SUMAR.SI y calcula el peso de cada una: <code>=B2/SUMA($B$2:$B$5)</code> con formato Porcentaje. Un gráfico circular muestra cómo se reparte el dinero.</p>',E'<p>Si Comida suma 250 de un total de 530, representa el 47,17 % del gasto.</p>',E'{"headers":["Categoría","Monto"],"rows":[["Comida",250],["Transporte",120],["Ocio",60],["Servicios",100]]}',NULL,4,E'active'),
(42,8,E'Registro de trabajadores',E'Calcular nóminas, promedios y bonificaciones.',E'<p>Una hoja de personal incluye nombre, cargo, departamento y salario. Con funciones puedes obtener la nómina total (<code>SUMA</code>), el promedio por departamento (<code>PROMEDIO.SI</code>), el número de empleados por área (<code>CONTAR.SI</code>) y bonificaciones condicionales con <code>SI</code>.</p>',E'<p>Para el salario promedio del departamento de Ventas: <code>=PROMEDIO.SI(B2:B5;"Ventas";C2:C5)</code>.</p>',E'{"headers":["Nombre","Departamento","Salario"],"rows":[["Carla","Ventas",900],["Diego","Ventas",1100],["Elena","Admin",1000],["Mario","Admin",800]]}',NULL,5,E'active');
INSERT INTO exercises (id,module_id,lesson_id,title,topic,difficulty,type,statement,instructions,data_json,answer_kind,correct_answer,tolerance,explanation,points,status) VALUES
(1,1,1,E'Usos de Excel',E'Concepto de Excel',E'basico',E'multiple_choice',E'¿Cuál de las siguientes tareas es la más adecuada para realizar en Excel?',NULL,NULL,E'option',NULL,0.01,E'Excel está pensado para organizar datos y calcular con ellos. Redactar cartas corresponde a un procesador de texto, y el video o el diseño gráfico a otras herramientas.',10,E'active'),
(2,1,2,E'Barra de fórmulas',E'Entorno de trabajo',E'basico',E'multiple_choice',E'¿Dónde se visualiza y edita el contenido real (la fórmula) de la celda seleccionada?',NULL,NULL,E'option',NULL,0.01,E'El cuadro de nombres indica la dirección de la celda; la barra de estado muestra resúmenes; la barra de fórmulas muestra y permite editar el contenido.',10,E'active'),
(3,1,3,E'Libro y hojas',E'Libros y hojas',E'basico',E'true_false',E'Un archivo de Excel recibe el nombre de libro y puede contener varias hojas de cálculo.',NULL,NULL,E'option',NULL,0.01,E'El archivo es el libro y dentro tiene tantas hojas como necesites.',10,E'active'),
(4,1,4,E'Dirección de una celda',E'Celdas y rangos',E'basico',E'analyze_table',E'Observa la hoja. ¿En qué celda está escrito el texto “Cuaderno”?',E'Escribe solo la dirección, por ejemplo B4.',E'{"headers":["Producto","Cantidad"],"rows":[["Lápiz",10],["Cuaderno",5],["Borrador",8]]}',E'text',E'A3',0.01,E'La columna A contiene los productos y “Cuaderno” está en la fila 3 (la fila 1 es el encabezado), por tanto su dirección es A3.',10,E'active'),
(5,1,5,E'Tipo de dato',E'Tipos de datos',E'basico',E'multiple_choice',E'Al escribir 15/03/2026 en una celda, Excel lo reconoce como:',NULL,NULL,E'option',NULL,0.01,E'Excel interpreta ese formato como una fecha y la guarda internamente como un número de serie, lo que permite calcular días entre fechas.',10,E'active'),
(6,1,6,E'Primera fórmula',E'Fórmulas',E'basico',E'complete_formula',E'Escribe la fórmula que, ubicada en C2, calcule el importe multiplicando la cantidad por el precio.',NULL,E'{"headers":["Cantidad","Precio","Importe"],"rows":[[4,2.5,""]]}',E'formula',E'=A2*B2||=B2*A2',0.01,E'La fórmula multiplica las celdas A2 y B2 con el operador *. Recuerda que empieza con =.',10,E'active'),
(7,2,7,E'Atajo de formato',E'Formato de celdas',E'basico',E'multiple_choice',E'¿Qué atajo de teclado abre el cuadro “Formato de celdas”?',NULL,NULL,E'option',NULL,0.01,E'Ctrl+1 abre Formato de celdas. Ctrl+F busca, Ctrl+P imprime y Ctrl+Z deshace.',10,E'active'),
(8,2,8,E'Formato porcentaje',E'Formato de números',E'basico',E'solve_operation',E'Escribes 0,15 en una celda y le aplicas el formato Porcentaje. ¿Qué número se mostrará (sin el símbolo %)?',NULL,NULL,E'number',E'15',0.01,E'El formato Porcentaje multiplica por 100 al mostrar: 0,15 × 100 = 15 %.',10,E'active'),
(9,2,9,E'Diseño de tablas',E'Bordes y colores',E'basico',E'true_false',E'Un buen diseño de tabla usa muchos colores distintos para que cada dato destaque.',NULL,NULL,E'option',NULL,0.01,E'Demasiados colores saturan y confunden. Lo recomendable es usar pocos colores con buen contraste.',10,E'active'),
(10,2,10,E'Combinar celdas',E'Combinar celdas',E'basico',E'multiple_choice',E'¿Por qué se recomienda no combinar celdas dentro de una tabla de datos?',NULL,NULL,E'option',NULL,0.01,E'Las celdas combinadas rompen la estructura de filas y columnas que necesitan ordenar y filtrar.',10,E'active'),
(11,2,11,E'Almohadillas ####',E'Ajuste de columnas',E'basico',E'multiple_choice',E'Una celda muestra “#####”. ¿Cuál es la causa más probable?',NULL,NULL,E'option',NULL,0.01,E'#### aparece cuando el ancho de la columna no alcanza para el valor. Se soluciona ensanchando la columna.',10,E'active'),
(12,2,12,E'Atajo de tablas',E'Tablas',E'basico',E'multiple_choice',E'¿Qué atajo convierte un rango de datos en una Tabla de Excel?',NULL,NULL,E'option',NULL,0.01,E'Ctrl+T crea la tabla. Ctrl+K inserta un hipervínculo y Ctrl+W cierra el libro.',10,E'active'),
(13,3,13,E'Sumar celdas',E'Suma',E'basico',E'solve_operation',E'Con los datos de la hoja, ¿qué valor devuelve la fórmula =B2+B3+B4?',NULL,E'{"headers":["Concepto","Monto"],"rows":[["Alquiler",500],["Servicios",120],["Comida",300]]}',E'number',E'920',0.01,E'500 + 120 + 300 = 920.',10,E'active'),
(14,3,14,E'Calcular saldo',E'Resta',E'basico',E'solve_operation',E'Con los datos de la hoja, ¿qué resultado da =B2-B3?',NULL,E'{"headers":["Concepto","Monto"],"rows":[["Ingresos",2500],["Gastos",1875]]}',E'number',E'625',0.01,E'2500 − 1875 = 625.',10,E'active'),
(15,3,15,E'Calcular importe',E'Multiplicación',E'basico',E'solve_operation',E'Un cuaderno cuesta 3,50 y compras 12. ¿Cuánto debes pagar en total?',NULL,NULL,E'number',E'42',0.01,E'12 × 3,50 = 42.',10,E'active'),
(16,3,16,E'Error de división',E'División',E'basico',E'multiple_choice',E'¿Qué error muestra Excel si escribes =A1/B1 y la celda B1 contiene 0?',NULL,NULL,E'option',NULL,0.01,E'Dividir entre cero genera #¡DIV/0!. #¡VALOR! aparece con tipos de dato incorrectos y #¿NOMBRE? con nombres de función desconocidos.',10,E'active'),
(17,3,17,E'Referencia absoluta',E'Referencias',E'intermedio',E'complete_formula',E'La tasa de IVA está en C2. Escribe la fórmula que calcule el IVA del precio de B3 de modo que, al copiarla hacia abajo, siga apuntando siempre a la tasa.',NULL,E'{"headers":["Producto","Precio","Tasa de IVA"],"rows":[["Lápiz",10,0.16],["Cuaderno",25,""],["Regla",8,""]]}',E'formula',E'=B3*$C$2||=$C$2*B3',0.01,E'La referencia a la tasa debe ser absoluta ($C$2) para que no cambie al copiar; el precio (B3) es relativo.',15,E'active'),
(18,3,18,E'Jerarquía de operadores',E'Operaciones combinadas',E'intermedio',E'solve_operation',E'¿Qué valor devuelve la fórmula =(8+4)/2*3-1?',NULL,NULL,E'number',E'17',0.01,E'Primero el paréntesis: 12. Luego 12/2 = 6; 6*3 = 18; finalmente 18−1 = 17.',15,E'active'),
(19,4,19,E'Usar SUMA',E'SUMA',E'basico',E'complete_formula',E'Escribe la fórmula que sume todas las ventas de la semana (B2:B6).',NULL,E'{"headers":["Día","Ventas"],"rows":[["Lunes",120],["Martes",150],["Miércoles",90],["Jueves",200],["Viernes",175]]}',E'formula',E'=SUMA(B2:B6)',0.01,E'SUMA recibe el rango B2:B6. El resultado es 120 + 150 + 90 + 200 + 175 = 735.',10,E'active'),
(20,4,20,E'Usar PROMEDIO',E'PROMEDIO',E'basico',E'solve_operation',E'¿Qué valor devuelve =PROMEDIO(B2:B5) con los datos de la hoja?',NULL,E'{"headers":["Alumno","Nota"],"rows":[["Ana",15],["Luis",12],["Marta",18],["Pedro",11]]}',E'number',E'14',0.01,E'(15 + 12 + 18 + 11) / 4 = 56 / 4 = 14.',10,E'active'),
(21,4,21,E'Usar MAX',E'MAX',E'basico',E'complete_formula',E'Escribe la fórmula que devuelva la venta más alta del rango B2:B6.',NULL,E'{"headers":["Día","Ventas"],"rows":[["Lunes",120],["Martes",150],["Miércoles",90],["Jueves",200],["Viernes",175]]}',E'formula',E'=MAX(B2:B6)',0.01,E'MAX devuelve el mayor valor del rango; en este caso, 200.',10,E'active'),
(22,4,22,E'Usar MIN',E'MIN',E'basico',E'solve_operation',E'¿Qué valor devuelve =MIN(B2:B6) con los datos de la hoja?',NULL,E'{"headers":["Ciudad","Temperatura"],"rows":[["Caracas",28],["Maracay",31],["Mérida",25],["Maracaibo",33],["Valencia",29]]}',E'number',E'25',0.01,E'El menor valor de 28, 31, 25, 33 y 29 es 25.',10,E'active'),
(23,4,23,E'Usar CONTAR',E'CONTAR',E'basico',E'solve_operation',E'¿Qué valor devuelve =CONTAR(A2:A6) con los datos de la hoja?',NULL,E'{"headers":["Lecturas"],"rows":[[10],["N\\/D"],[25],[""],[40]]}',E'number',E'3',0.01,E'Solo hay tres números: 10, 25 y 40. El texto “N/D” y la celda vacía no se cuentan.',10,E'active'),
(24,4,24,E'Usar CONTARA',E'CONTARA',E'basico',E'solve_operation',E'¿Qué valor devuelve =CONTARA(A2:A6) con los datos de la hoja?',NULL,E'{"headers":["Lecturas"],"rows":[[10],["N\\/D"],[25],[""],[40]]}',E'number',E'4',0.01,E'CONTARA cuenta las celdas no vacías: 10, “N/D”, 25 y 40. Son 4.',10,E'active'),
(25,5,25,E'Usar SI',E'SI',E'intermedio',E'complete_formula',E'Escribe en C2 una fórmula que muestre "Aprobado" si la nota de B2 es mayor o igual a 10 y "Reprobado" en caso contrario.',NULL,E'{"headers":["Alumno","Nota","Condición"],"rows":[["Ana",15,""]]}',E'formula',E'=SI(B2>=10;"Aprobado";"Reprobado")',0.01,E'La prueba lógica es B2>=10; si se cumple devuelve "Aprobado", si no, "Reprobado". Puedes usar ; o , como separador.',15,E'active'),
(26,5,26,E'Usar CONTAR.SI',E'CONTAR.SI',E'intermedio',E'solve_operation',E'¿Qué valor devuelve =CONTAR.SI(B2:B6;"Aprobado") con los datos de la hoja?',NULL,E'{"headers":["Alumno","Condición"],"rows":[["Ana","Aprobado"],["Luis","Reprobado"],["Marta","Aprobado"],["Pedro","Aprobado"],["Sofía","Reprobado"]]}',E'number',E'3',0.01,E'Hay tres celdas con el texto Aprobado: Ana, Marta y Pedro.',15,E'active'),
(27,5,27,E'Usar SUMAR.SI',E'SUMAR.SI',E'intermedio',E'solve_operation',E'¿Qué valor devuelve =SUMAR.SI(A2:A6;"Ana";B2:B6) con los datos de la hoja?',NULL,E'{"headers":["Vendedor","Ventas"],"rows":[["Ana",500],["Luis",300],["Ana",450],["Luis",200],["Marta",600]]}',E'number',E'950',0.01,E'Las ventas de Ana son 500 y 450: 500 + 450 = 950.',15,E'active'),
(28,5,28,E'Usar PROMEDIO.SI',E'PROMEDIO.SI',E'intermedio',E'solve_operation',E'¿Qué valor devuelve =PROMEDIO.SI(A2:A6;"A";B2:B6) con los datos de la hoja?',NULL,E'{"headers":["Sección","Nota"],"rows":[["A",14],["B",12],["A",16],["B",10],["A",18]]}',E'number',E'16',0.01,E'Las notas de la sección A son 14, 16 y 18. (14 + 16 + 18) / 3 = 16.',15,E'active'),
(29,6,29,E'Ordenar una sola columna',E'Ordenar',E'basico',E'multiple_choice',E'Ordenaste solamente la columna B de una tabla y los nombres de la columna A no se movieron. ¿Qué ocurrió?',NULL,NULL,E'option',NULL,0.01,E'Cada fila representa un registro; si solo una columna cambia de orden, los datos quedan asociados a la persona equivocada.',10,E'active'),
(30,6,30,E'Efecto de un filtro',E'Filtros',E'basico',E'true_false',E'Al aplicar un filtro, las filas que no cumplen el criterio se eliminan definitivamente.',NULL,NULL,E'option',NULL,0.01,E'Los filtros solo ocultan filas temporalmente; los datos siguen en la hoja y reaparecen al quitar el filtro.',10,E'active'),
(31,6,31,E'Usar BUSCARV',E'BUSCARV',E'intermedio',E'complete_formula',E'Escribe una fórmula que busque el precio (columna 3) del código 102 en la tabla A2:C4, con coincidencia exacta.',NULL,E'{"headers":["Código","Producto","Precio"],"rows":[[101,"Lápiz",0.5],[102,"Cuaderno",2.5],[103,"Regla",1.2]]}',E'formula',E'=BUSCARV(102;A2:C4;3;FALSO)||=BUSCARV(102;A2:C4;3;0)',0.01,E'BUSCARV busca 102 en la primera columna de A2:C4 y devuelve el valor de la columna 3 (el precio 2,5). FALSO exige coincidencia exacta.',15,E'active'),
(32,6,32,E'Lista desplegable',E'Validación de datos',E'basico',E'multiple_choice',E'¿Qué criterio de validación permite crear una lista desplegable con opciones fijas?',NULL,NULL,E'option',NULL,0.01,E'El criterio Lista permite elegir entre valores predefinidos y evita errores de escritura.',10,E'active'),
(33,6,33,E'Herramienta adecuada',E'Formato condicional',E'basico',E'multiple_choice',E'Quieres resaltar automáticamente en rojo las notas menores a 10. ¿Qué herramienta usas?',NULL,NULL,E'option',NULL,0.01,E'El formato condicional aplica formato según el valor, y se actualiza solo cuando los datos cambian.',10,E'active'),
(34,7,34,E'Gráfico para comparar',E'Gráficos de barras',E'basico',E'multiple_choice',E'¿Qué gráfico es el ideal para comparar las ventas de cinco sucursales?',NULL,NULL,E'option',NULL,0.01,E'Las barras o columnas facilitan la comparación entre categorías independientes.',10,E'active'),
(35,7,35,E'Cuándo usar circular',E'Gráficos circulares',E'basico',E'true_false',E'Un gráfico circular es adecuado para mostrar la evolución de las ventas mes a mes durante tres años.',NULL,NULL,E'option',NULL,0.01,E'Para evolución en el tiempo es mejor un gráfico de líneas. El circular sirve para partes de un todo.',10,E'active'),
(36,7,36,E'Gráfico de tendencia',E'Gráficos de líneas',E'basico',E'multiple_choice',E'Para mostrar cómo cambia la temperatura cada hora a lo largo de un día, el gráfico más adecuado es:',NULL,NULL,E'option',NULL,0.01,E'Los datos ordenados en el tiempo se representan mejor con líneas, porque muestran la tendencia.',10,E'active'),
(37,7,37,E'Leer datos',E'Interpretación',E'basico',E'analyze_table',E'Según la tabla (que sería la base de un gráfico), ¿en qué mes se registró la mayor venta?',NULL,E'{"headers":["Mes","Ventas"],"rows":[["Enero",1000],["Febrero",1200],["Marzo",900],["Abril",1500]]}',E'text',E'Abril||Abr',0.01,E'La venta de abril (1500) supera a las de enero (1000), febrero (1200) y marzo (900).',10,E'active'),
(38,8,38,E'Total de ventas',E'Control de ventas',E'basico',E'solve_operation',E'¿Cuál es el total general de la venta (suma de cantidad × precio de cada producto)?',NULL,E'{"headers":["Producto","Cantidad","Precio"],"rows":[["Camisa",3,20],["Pantalón",2,35],["Gorra",5,8]]}',E'number',E'170',0.01,E'Camisa: 3×20 = 60; Pantalón: 2×35 = 70; Gorra: 5×8 = 40. Total: 60 + 70 + 40 = 170.',10,E'active'),
(39,8,39,E'Alerta de reposición',E'Control de inventario',E'intermedio',E'complete_formula',E'Escribe en D2 una fórmula que muestre "Reponer" si la existencia (B2) es menor que el mínimo (C2) y "OK" en caso contrario.',NULL,E'{"headers":["Producto","Existencia","Mínimo"],"rows":[["Arroz",8,10],["Harina",25,12],["Aceite",4,6]]}',E'formula',E'=SI(B2<C2;"Reponer";"OK")',0.01,E'La condición es B2<C2. Si se cumple devuelve "Reponer"; si no, "OK".',15,E'active'),
(40,8,40,E'Promedio de un alumno',E'Calificaciones',E'basico',E'solve_operation',E'¿Cuál es el promedio de Ana (=PROMEDIO(B2:D2))?',NULL,E'{"headers":["Alumno","Nota 1","Nota 2","Nota 3"],"rows":[["Ana",16,14,18],["Luis",10,8,9]]}',E'number',E'16',0.01,E'(16 + 14 + 18) / 3 = 48 / 3 = 16.',10,E'active'),
(41,8,41,E'Peso de una categoría',E'Control de gastos',E'intermedio',E'solve_operation',E'¿Qué porcentaje del gasto total representa Transporte? Escribe el valor con dos decimales y sin el símbolo %.',E'Escribe solo el número, por ejemplo 12.34',E'{"headers":["Categoría","Monto"],"rows":[["Comida",250],["Transporte",120],["Ocio",60],["Servicios",100]]}',E'number',E'22.64',0.05,E'Total: 250 + 120 + 60 + 100 = 530. Transporte: 120 / 530 = 0,2264 → 22,64 %.',15,E'active'),
(42,8,42,E'Promedio por departamento',E'Registro de trabajadores',E'intermedio',E'solve_operation',E'¿Qué valor devuelve =PROMEDIO.SI(B2:B5;"Ventas";C2:C5) con los datos de la hoja?',NULL,E'{"headers":["Nombre","Departamento","Salario"],"rows":[["Carla","Ventas",900],["Diego","Ventas",1100],["Elena","Admin",1000],["Mario","Admin",800]]}',E'number',E'1000',0.01,E'Los salarios de Ventas son 900 y 1100: (900 + 1100) / 2 = 1000.',15,E'active'),
(43,1,NULL,E'Inicio de una fórmula',E'Fórmulas',E'basico',E'true_false',E'Toda fórmula en Excel debe comenzar con el signo igual (=).',NULL,NULL,E'option',NULL,0.01,E'Sin el signo = Excel interpreta lo escrito como texto.',10,E'active'),
(44,1,NULL,E'Dirección de celda',E'Celdas y rangos',E'basico',E'multiple_choice',E'¿Cuál es la dirección de la celda ubicada en la columna C, fila 5?',NULL,NULL,E'option',NULL,0.01,E'Primero va la letra de la columna y después el número de la fila: C5.',10,E'active'),
(45,1,NULL,E'Leer una celda',E'Celdas y rangos',E'basico',E'analyze_table',E'Observa la hoja. ¿Qué valor contiene la celda C3?',NULL,E'{"headers":["Producto","Cantidad","Precio"],"rows":[["Lápiz",10,0.4],["Cuaderno",5,2.5],["Borrador",8,0.75]]}',E'number',E'2.5',0.01,E'C3 está en la columna Precio y en la fila 3, que corresponde al Cuaderno: 2,5.',10,E'active'),
(46,2,NULL,E'Formato moneda',E'Formato de números',E'basico',E'multiple_choice',E'¿Qué formato de número debes aplicar para mostrar 1500 como $1.500,00?',NULL,NULL,E'option',NULL,0.01,E'El formato Moneda agrega el símbolo y los decimales, sin cambiar el valor.',10,E'active'),
(47,2,NULL,E'Formato y valor',E'Formato de números',E'basico',E'true_false',E'Aplicar el formato Moneda a un número cambia su valor real en los cálculos.',NULL,NULL,E'option',NULL,0.01,E'El formato solo cambia la apariencia; el valor almacenado es el mismo.',10,E'active'),
(48,3,NULL,E'Potencias',E'Operaciones combinadas',E'intermedio',E'solve_operation',E'¿Qué valor devuelve la fórmula =2^3+10/5?',NULL,NULL,E'number',E'10',0.01,E'Primero la potencia (2^3 = 8) y la división (10/5 = 2); luego la suma: 8 + 2 = 10.',15,E'active'),
(49,3,NULL,E'Calcular un saldo',E'Resta',E'basico',E'complete_formula',E'Con los ingresos en B2 y los gastos en B3, escribe la fórmula que calcule el saldo.',NULL,E'{"headers":["Concepto","Monto"],"rows":[["Ingresos",2500],["Gastos",1875]]}',E'formula',E'=B2-B3',0.01,E'El saldo es ingresos menos gastos.',10,E'active'),
(50,3,NULL,E'Precio con descuento',E'Operaciones combinadas',E'intermedio',E'practical',E'Un producto cuesta 80 y tiene un descuento del 15 %. ¿Cuál es el precio final?',NULL,NULL,E'number',E'68',0.01,E'Descuento: 80 × 0,15 = 12. Precio final: 80 − 12 = 68. En Excel: =80*(1-0,15).',15,E'active');
INSERT INTO exercises (id,module_id,lesson_id,title,topic,difficulty,type,statement,instructions,data_json,answer_kind,correct_answer,tolerance,explanation,points,status) VALUES
(51,4,NULL,E'Identificar CONTAR',E'Funciones básicas',E'basico',E'identify_function',E'¿Qué función cuenta cuántas celdas de un rango contienen números?',NULL,NULL,E'option',NULL,0.01,E'CONTAR solo considera celdas numéricas. CONTARA cuenta todas las celdas no vacías.',10,E'active'),
(52,4,NULL,E'Identificar MIN',E'Funciones básicas',E'basico',E'identify_function',E'Necesitas conocer el precio más bajo de una lista. ¿Qué función usas?',NULL,NULL,E'option',NULL,0.01,E'MIN devuelve el valor más pequeño de un rango.',10,E'active'),
(53,4,NULL,E'Promedio de ventas',E'PROMEDIO',E'basico',E'complete_formula',E'Escribe la fórmula que calcule el promedio de las ventas del rango B2:B6.',NULL,E'{"headers":["Día","Ventas"],"rows":[["Lunes",120],["Martes",150],["Miércoles",90],["Jueves",200],["Viernes",175]]}',E'formula',E'=PROMEDIO(B2:B6)',0.01,E'PROMEDIO(B2:B6) = 735 / 5 = 147.',10,E'active'),
(54,4,NULL,E'Días con buenas ventas',E'Análisis de tablas',E'intermedio',E'analyze_table',E'Analiza la hoja. ¿En cuántos días las ventas fueron superiores a 100?',NULL,E'{"headers":["Día","Ventas"],"rows":[["Lunes",120],["Martes",150],["Miércoles",90],["Jueves",200],["Viernes",175]]}',E'number',E'4',0.01,E'Superan 100: lunes (120), martes (150), jueves (200) y viernes (175). El miércoles (90) no.',15,E'active'),
(55,4,NULL,E'Nota más alta',E'MAX',E'intermedio',E'practical',E'Un docente tiene las notas de 30 alumnos en el rango B2:B31. Escribe la fórmula para obtener la nota más alta.',NULL,NULL,E'formula',E'=MAX(B2:B31)',0.01,E'MAX devuelve el mayor valor del rango B2:B31.',15,E'active'),
(56,5,NULL,E'Contar con criterio',E'CONTAR.SI',E'intermedio',E'complete_formula',E'Escribe la fórmula que cuente cuántas ventas del rango B2:B6 son mayores que 150.',NULL,E'{"headers":["Día","Ventas"],"rows":[["Lunes",120],["Martes",150],["Miércoles",90],["Jueves",200],["Viernes",175]]}',E'formula',E'=CONTAR.SI(B2:B6;">150")',0.01,E'El criterio va entre comillas: ">150". Superan 150 las ventas del jueves (200) y del viernes (175): son 2.',15,E'active'),
(57,5,NULL,E'Sumar por vendedor',E'SUMAR.SI',E'avanzado',E'complete_formula',E'Escribe la fórmula que sume las ventas (B2:B6) del vendedor "Luis" (columna A2:A6).',NULL,E'{"headers":["Vendedor","Ventas"],"rows":[["Ana",500],["Luis",300],["Ana",450],["Luis",200],["Marta",600]]}',E'formula',E'=SUMAR.SI(A2:A6;"Luis";B2:B6)',0.01,E'SUMAR.SI(rango; criterio; rango_suma). Luis suma 300 + 200 = 500.',20,E'active'),
(58,5,NULL,E'Resultado de SI',E'SI',E'intermedio',E'multiple_choice',E'¿Qué devuelve la fórmula =SI(5>3;"Sí";"No")?',NULL,NULL,E'option',NULL,0.01,E'La condición 5>3 es verdadera, por lo que devuelve el segundo argumento: "Sí".',15,E'active'),
(59,5,NULL,E'Comisión por ventas',E'SI',E'avanzado',E'practical',E'Una empresa paga el 10 % de comisión si las ventas (B2) son de 1000 o más, y 5 % si son menores. Escribe la fórmula para C2.',NULL,NULL,E'formula',E'=SI(B2>=1000;B2*0.1;B2*0.05)||=SI(B2>=1000;B2*10%;B2*5%)||=B2*SI(B2>=1000;0.1;0.05)||=SI(B2>=1000;B2*0,1;B2*0,05)',0.01,E'Si B2>=1000 se multiplica por 0,10; en caso contrario por 0,05.',25,E'active'),
(60,5,NULL,E'Criterios en CONTAR.SI',E'CONTAR.SI',E'intermedio',E'true_false',E'CONTAR.SI permite usar criterios con operadores, como ">10".',NULL,NULL,E'option',NULL,0.01,E'Los criterios pueden ser valores o comparaciones entre comillas.',15,E'active'),
(61,6,NULL,E'Primera columna en BUSCARV',E'BUSCARV',E'intermedio',E'true_false',E'En BUSCARV, el valor buscado debe encontrarse en la primera columna de la matriz.',NULL,NULL,E'option',NULL,0.01,E'BUSCARV siempre busca en la primera columna de la matriz y devuelve datos de columnas a su derecha.',15,E'active'),
(62,6,NULL,E'Atajo de filtros',E'Filtros',E'basico',E'multiple_choice',E'¿Qué atajo activa o desactiva los filtros de una tabla?',NULL,NULL,E'option',NULL,0.01,E'Ctrl+Mayús+L alterna el filtro automático.',10,E'active'),
(63,6,NULL,E'Limitar valores',E'Validación de datos',E'intermedio',E'multiple_choice',E'¿Qué herramienta permite que una celda solo acepte números enteros entre 1 y 20?',NULL,NULL,E'option',NULL,0.01,E'La validación de datos restringe lo que se puede escribir y muestra un mensaje de error.',15,E'active'),
(64,7,NULL,E'Partes de un todo',E'Gráficos circulares',E'basico',E'multiple_choice',E'¿Qué gráfico usarías para mostrar qué porción del presupuesto se destina a cada área?',NULL,NULL,E'option',NULL,0.01,E'El circular muestra la proporción de cada parte respecto del total.',10,E'active'),
(65,7,NULL,E'Caída de ventas',E'Interpretación',E'intermedio',E'analyze_table',E'Según la tabla, ¿cuántas unidades cayeron las ventas de febrero a marzo?',NULL,E'{"headers":["Mes","Ventas"],"rows":[["Enero",1000],["Febrero",1200],["Marzo",900],["Abril",1500]]}',E'number',E'300',0.01,E'Febrero: 1200; marzo: 900. La caída fue de 1200 − 900 = 300.',15,E'active'),
(66,8,NULL,E'Valor del inventario',E'Control de inventario',E'intermedio',E'practical',E'¿Cuál es el valor total del inventario (existencia × costo de cada producto)?',NULL,E'{"headers":["Producto","Existencia","Costo"],"rows":[["Tornillos",40,2.5],["Tuercas",30,1.2]]}',E'number',E'136',0.01,E'Tornillos: 40×2,5 = 100; Tuercas: 30×1,2 = 36. Total: 136.',15,E'active'),
(67,8,NULL,E'Bonificaciones',E'Registro de trabajadores',E'avanzado',E'practical',E'La empresa paga un bono del 8 % a los trabajadores que ganan menos de 1000. ¿Cuánto se paga en bonos en total?',NULL,E'{"headers":["Nombre","Salario"],"rows":[["Carla",900],["Diego",1100],["Elena",1000],["Mario",800]]}',E'number',E'136',0.01,E'Cumplen: Carla (900) y Mario (800). Bonos: 72 + 64 = 136.',20,E'active'),
(68,8,NULL,E'Promedio de calificaciones',E'Calificaciones',E'basico',E'practical',E'Las notas de un alumno son 12, 14, 16 y 18. ¿Cuál es su promedio?',NULL,NULL,E'number',E'15',0.01,E'(12 + 14 + 16 + 18) / 4 = 60 / 4 = 15.',10,E'active'),
(69,8,NULL,E'Productos a reponer',E'Control de inventario',E'avanzado',E'analyze_table',E'Analiza la hoja. ¿Cuántos productos tienen una existencia menor que el mínimo?',NULL,E'{"headers":["Producto","Existencia","Mínimo"],"rows":[["Arroz",8,10],["Harina",25,12],["Aceite",4,6]]}',E'number',E'2',0.01,E'Arroz (8 < 10) y Aceite (4 < 6) necesitan reposición. Harina (25 ≥ 12) no.',20,E'active'),
(70,8,NULL,E'Función para contar reprobados',E'Calificaciones',E'intermedio',E'identify_function',E'Quieres saber cuántos alumnos reprobaron en una lista con la columna “Condición”. ¿Qué función usas?',NULL,NULL,E'option',NULL,0.01,E'CONTAR.SI cuenta las celdas que cumplen un criterio, por ejemplo "Reprobado".',15,E'active');
