INSERT INTO challenges (id,title,difficulty,situation,objective,data_json,instructions,est_minutes,points,answer_kind,correct_answer,tolerance,hint,feedback_ok,feedback_fail,position,status) VALUES
(1,E'Reto 1: Total de una compra',E'basico',E'Estás haciendo las compras de la semana en el supermercado y quieres saber cuánto vas a pagar antes de llegar a la caja.',E'Calcular el total de la compra.',E'{"headers":["Producto","Cantidad","Precio unitario"],"rows":[["Arroz",2,1.8],["Aceite",1,4.5],["Leche",6,1.1],["Huevos",2,3.2]]}',E'Calcula el importe de cada producto (cantidad × precio) y súmalos. Puedes usar =SUMAPRODUCTO(B2:B5;C2:C5). Escribe el total.',5,20,E'number',E'21.1',0.01,E'Multiplica cantidad por precio en cada fila y suma los resultados.',E'¡Correcto! 3,6 + 4,5 + 6,6 + 6,4 = 21,10.',E'No coincide. Recuerda multiplicar la cantidad por el precio de cada producto antes de sumar.',1,E'active'),
(2,E'Reto 2: Promedio de calificaciones',E'basico',E'La profesora necesita el promedio del grupo en el primer parcial para presentarlo en la reunión de docentes.',E'Determinar el promedio de las notas del curso.',E'{"headers":["Alumno","Nota"],"rows":[["Ana",14],["Luis",17],["Marta",12],["Pedro",19],["Sofía",15],["Juan",10],["Rosa",16],["Mario",13]]}',E'Usa la función PROMEDIO sobre el rango B2:B9 y escribe el resultado.',5,20,E'number',E'14.5',0.01,E'Usa =PROMEDIO(B2:B9).',E'¡Excelente! La suma es 116 y entre 8 alumnos da 14,5.',E'Revisa el rango: deben entrar las 8 notas y ninguna celda de texto.',2,E'active'),
(3,E'Reto 3: La venta más alta',E'basico',E'Una tienda registra las ventas de la semana de siete vendedores y el gerente desea premiar al que logró la venta más alta.',E'Identificar el valor de la venta más alta.',E'{"headers":["Vendedor","Ventas"],"rows":[["Ana",1250],["Luis",980],["Marta",1420],["Pedro",1105],["Sofía",1390],["Juan",870],["Rosa",1315]]}',E'Usa la función MAX sobre el rango B2:B8 y escribe el valor.',5,25,E'number',E'1420',0.01,E'La función MAX devuelve el valor mayor de un rango.',E'¡Correcto! La mayor venta es de Marta: 1420.',E'Ese no es el mayor valor. Usa =MAX(B2:B8).',3,E'active'),
(4,E'Reto 4: ¿Quiénes aprobaron?',E'intermedio',E'En una lista de notas, la nota mínima aprobatoria es 10. El docente quiere saber cuántos alumnos aprobaron.',E'Determinar cuántos alumnos aprobaron (nota ≥ 10).',E'{"headers":["Alumno","Nota"],"rows":[["Ana",15],["Luis",8],["Marta",10],["Pedro",9],["Sofía",18],["Juan",7],["Rosa",12]]}',E'Crea una columna con =SI(B2>=10;"Aprobado";"Reprobado") y cuenta con CONTAR.SI, o usa directamente =CONTAR.SI(B2:B8;">=10"). Escribe la cantidad.',10,35,E'number',E'4',0,E'Recuerda que la nota 10 también aprueba (>=).',E'¡Muy bien! Aprobaron Ana, Marta, Sofía y Rosa: 4 alumnos.',E'Verifica la condición: la nota 10 ya es aprobatoria.',4,E'active'),
(5,E'Reto 5: Ingresos de una empresa',E'intermedio',E'Una pequeña empresa vende un producto cuyo precio cambió en marzo. Debe calcular los ingresos totales del primer cuatrimestre.',E'Calcular los ingresos totales (unidades × precio) de los cuatro meses.',E'{"headers":["Mes","Unidades","Precio unitario"],"rows":[["Enero",120,15],["Febrero",150,15],["Marzo",90,18],["Abril",200,18]]}',E'Calcula el ingreso de cada mes (unidades × precio) y suma los cuatro. Escribe el total.',10,40,E'number',E'9270',0.01,E'Cada mes tiene su propio precio; no multipliques el total de unidades por un solo precio.',E'¡Perfecto! 1800 + 2250 + 1620 + 3600 = 9270.',E'Revisa que cada mes use su precio. Enero y febrero: 15; marzo y abril: 18.',5,E'active'),
(6,E'Reto 6: Organiza un inventario',E'avanzado',E'Una ferretería actualiza su inventario y necesita conocer el valor total de las existencias para el balance de fin de mes.',E'Calcular el valor total del inventario (existencia × costo).',E'{"headers":["Producto","Existencia","Costo","Mínimo"],"rows":[["Tornillos",120,0.25,100],["Tuercas",80,0.3,100],["Clavos",300,0.1,150],["Arandelas",60,0.15,80],["Martillos",15,12,10],["Alicates",8,9.5,10]]}',E'Multiplica existencia por costo en cada fila y suma (SUMAPRODUCTO(B2:B7;C2:C7)). Escribe el valor total.',15,50,E'number',E'349',0.01,E'Valor por producto = existencia × costo. Luego suma todos.',E'¡Genial! 30 + 24 + 30 + 9 + 180 + 76 = 349.',E'No coincide. Comprueba que usas la columna de costo y no la de mínimo.',6,E'active'),
(7,E'Reto 7: Comisiones por ventas',E'avanzado',E'La empresa paga una comisión del 5 % únicamente sobre las ventas superiores a 1000. Hay que calcular el total de comisiones a pagar.',E'Calcular el total de comisiones (solo ventas mayores a 1000).',E'{"headers":["Vendedor","Ventas"],"rows":[["Ana",1250],["Luis",980],["Marta",1420],["Pedro",1105],["Sofía",1390],["Juan",870],["Rosa",1315]]}',E'Suma solo las ventas mayores a 1000 con SUMAR.SI(B2:B8;">1000") y multiplica por 5 %.',15,50,E'number',E'324',0.01,E'Usa SUMAR.SI con el criterio ">1000" y multiplica por 0,05.',E'¡Correcto! Las ventas válidas suman 6480 y el 5 % es 324.',E'Revisa el criterio: solo cuentan las ventas mayores a 1000, y la comisión es 5 %.',7,E'active'),
(8,E'Reto 8: Promedio por sección',E'avanzado',E'Tres secciones presentaron el mismo examen. La coordinación quiere comparar el rendimiento de la sección B.',E'Calcular el promedio de notas de la sección B.',E'{"headers":["Sección","Nota"],"rows":[["A",14],["B",12],["A",16],["C",9],["B",15],["C",11],["A",18],["B",13],["C",10]]}',E'Usa =PROMEDIO.SI(A2:A10;"B";B2:B10). Escribe el resultado con dos decimales.',15,45,E'number',E'13.33',0.01,E'PROMEDIO.SI promedia solo las filas cuyo criterio coincide.',E'¡Muy bien! (12 + 15 + 13) / 3 = 13,33.',E'Verifica que promedias solo las notas de la sección B.',8,E'active');
INSERT INTO practical_cases (id,category,title,context,problem,data_json,instructions,criteria,mode,questions_json,points,status) VALUES
(1,E'Administración',E'Control de gastos del hogar',E'Una familia quiere conocer en qué se va su dinero cada mes. Llevan un registro simple con el concepto, la categoría y el monto de cada gasto.',E'Analiza el registro de gastos de octubre y responde a las preguntas de la administración familiar.',E'{"headers":["Concepto","Categoría","Monto"],"rows":[["Alquiler","Vivienda",450],["Electricidad","Servicios",62.5],["Agua","Servicios",18],["Internet","Servicios",30],["Mercado","Alimentación",280],["Transporte","Transporte",75],["Cine","Ocio",40]]}',E'Usa SUMA y SUMAR.SI en Excel (o en cálculo manual) sobre los datos y escribe los resultados.',E'Resultados exactos; uso correcto de funciones de suma por criterio.',E'platform',E'[{"label":"Total de gastos del mes","answer":955.5,"kind":"number","tolerance":0.01},{"label":"Total gastado en la categoría Servicios","answer":110.5,"kind":"number","tolerance":0.01},{"label":"Concepto con el mayor gasto","answer":"Alquiler","kind":"text","tolerance":0.01},{"label":"Si el ingreso del mes fue 1000, ¿cuánto dinero sobra?","answer":44.5,"kind":"number","tolerance":0.01}]',50,E'active'),
(2,E'Administración',E'Presupuesto mensual (entrega en Excel)',E'Una microempresa de servicios prepara su presupuesto mensual y debe compararlo con lo realmente ejecutado.',E'Completa la plantilla: calcula la diferencia entre lo presupuestado y lo real, la fila de totales y agrega un gráfico de columnas comparando ambos montos.',E'{"headers":["Concepto","Presupuestado","Real","Diferencia"],"rows":[["Alquiler del local",600,600,""],["Servicios",150,172,""],["Publicidad",200,140,""],["Materiales",350,410,""],["Transporte",120,95,""],["Totales","","",""]]}',E'Descarga la plantilla, completa la columna Diferencia (=B2-C2), calcula los totales con SUMA, aplica formato de moneda y agrega un gráfico. Sube el archivo (.xlsx).',E'Fórmulas correctas (40 %), totales (20 %), formato (20 %) y gráfico (20 %).',E'file',NULL,60,E'active'),
(3,E'Ventas',E'Registro de ventas de tecnología',E'Una tienda de tecnología registra las unidades vendidas y el precio de cada producto durante la semana.',E'Calcula el importe de cada producto y analiza los resultados de la semana.',E'{"headers":["Producto","Unidades","Precio unitario"],"rows":[["Laptop",3,650],["Mouse",25,12],["Teclado",15,28],["Monitor",6,140]]}',E'Importe = unidades × precio. Con los importes responde las preguntas.',E'Resultados exactos.',E'platform',E'[{"label":"Importe total de ventas de la semana","answer":3510,"kind":"number","tolerance":0.01},{"label":"Total de unidades vendidas","answer":49,"kind":"number","tolerance":0.01},{"label":"Importe del producto más vendido en unidades (Mouse)","answer":300,"kind":"number","tolerance":0.01},{"label":"¿Qué producto generó el mayor importe?","answer":"Laptop","kind":"text","tolerance":0.01}]',50,E'active'),
(4,E'Inventario',E'Control de existencias (entrega en Excel)',E'Un almacén de materiales de oficina necesita saber el valor de lo que tiene y qué productos debe reponer.',E'Completa la plantilla: calcula el valor de cada producto, el valor total del inventario y una columna que indique "Reponer" u "OK".',E'{"headers":["Producto","Existencia","Costo unitario","Mínimo","Valor","Estado"],"rows":[["Resmas de papel",40,4.5,50,"",""],["Bolígrafos (caja)",18,6,10,"",""],["Carpetas",120,0.8,100,"",""],["Tóner",5,38,6,"",""],["Grapadoras",14,7.5,8,"",""]]}',E'Valor = existencia × costo. Estado: =SI(B2<D2;"Reponer";"OK"). Aplica formato condicional para resaltar "Reponer" y calcula el valor total con SUMA. Sube el archivo.',E'Cálculos correctos (50 %), condición con SI (30 %), formato condicional y total (20 %).',E'file',NULL,60,E'active'),
(5,E'Recursos Humanos',E'Nómina y promedios salariales',E'El departamento de recursos humanos de una empresa mediana debe presentar un informe de sueldos al gerente general.',E'Analiza la nómina del área administrativa y responde.',E'{"headers":["Nombre","Cargo","Salario base"],"rows":[["Carla","Analista",1200],["Diego","Analista",1250],["Elena","Gerente",2400],["Mario","Asistente",800],["Lucía","Asistente",850]]}',E'Usa SUMA, PROMEDIO y CONTAR.SI como apoyo.',E'Resultados exactos.',E'platform',E'[{"label":"Total de la nómina mensual","answer":6500,"kind":"number","tolerance":0.01},{"label":"Salario promedio de toda la plantilla","answer":1300,"kind":"number","tolerance":0.01},{"label":"Salario promedio de los Asistentes","answer":825,"kind":"number","tolerance":0.01},{"label":"¿Cuántos empleados ganan más que el promedio de la plantilla?","answer":1,"kind":"number","tolerance":0}]',50,E'active'),
(6,E'Educación',E'Registro de calificaciones del curso',E'Un docente de Paquetes Informáticos registra los tres parciales de sus alumnos y debe calcular promedios y aprobados (nota mínima 10).',E'Calcula el promedio de cada alumno y los indicadores del curso.',E'{"headers":["Alumno","Parcial 1","Parcial 2","Parcial 3"],"rows":[["Ana",14,16,18],["Luis",10,8,9],["Marta",17,18,19],["Pedro",12,11,13],["Sofía",9,10,8]]}',E'Calcula =PROMEDIO(B2:D2) para cada alumno y responde.',E'Resultados exactos.',E'platform',E'[{"label":"Promedio de Marta","answer":18,"kind":"number","tolerance":0.01},{"label":"Cantidad de alumnos aprobados (promedio ≥ 10)","answer":3,"kind":"number","tolerance":0},{"label":"Promedio general del grupo (promedio de los cinco promedios)","answer":12.8,"kind":"number","tolerance":0.01}]',50,E'active');
